@spec tm_note_lane_carry_spec  src=tests/specs/tm_note_lane_carry_spec.lua  loc=98  cases=4
@exercises trackerManager (h.tm)
@surface   tm:getChannel, tm:addEvent, tm:flush
@harness   mk

# Intent
  tv's cell carry keys on a note lane's `events` table identity (trackerView's prevBuilt), so a
  lane whose contents did not change must keep that table across a rebuild, and a lane whose
  contents did change must swap it. exciseNotes used to re-clone every lane of an interval-dirty
  channel, so a one-note edit made tv re-place the whole channel. This pins the shed in both
  directions, including the tail walk's reach into a lane no seed covered.

# Helpers
  @fn note(ppq, pitch, lane, extra)  @ 9-14
  @fn laneEvents(h, lane)  @ 16-18
  @fn twoLanes(harness)  @ 22-30
      -- chan 1 holding one note in lane 1 (row 0) and one in lane 2 (row 960), with both lanes'
      -- events tables captured by identity. The edit each case then makes seeds row 240 only.

# Cases
  @case 'a lane the edit never touched keeps its events table'  [harness]  @ 34-41
  @case 'the edited lane sheds its events table'  [harness]  @ 44-52
  @case 'a seeded row drops the co-row cell in a lane the seed never named'  [harness]  @ 55-71
  @case 'a nudge sheds the neighbour lane no seed covered'  [harness]  @ 74-96

# Uses (outbound edges)
  @use call tm:getChannel  @ 17
  @use call tm:addEvent  @ 24,25,38,48,61,62,67,82,91
  @use call tm:flush  @ 26,38,48,63,67,83,91

# Fields (r read / w write incl. constructor keys)
  @field w chan  @ 10
  @field r columns  @ 17
  @field w delay  @ 11,82
  @field r delayC  @ 89,93
  @field w detune  @ 11
  @field w endppq  @ 10
  @field w evType  @ 10
  @field r events  @ 17
  @field w lane  @ 11
  @field w name  @ 34,44,55,74
  @field r notes  @ 17
  @field w pitch  @ 10
  @field r ppq  @ 88
  @field w ppq  @ 10
  @field w run  @ 35,45,56,75
  @field w vel  @ 11
